DO $$ DECLARE r record; BEGIN FOR r IN SELECT proname, pg_get_function_identity_arguments(oid) AS args FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND prosecdef=true AND (proconfig IS NULL OR NOT array_to_string(proconfig,',') LIKE '%pg_temp%') LOOP EXECUTE format('ALTER FUNCTION public.%I(%s) SET search_path = public, pg_temp', r.proname, r.args); END LOOP; END; $$
